import axios from "axios";
import { Pool } from "pg";
import { getUser, importUser, countUsersByDomain } from "./users";

const pool = new Pool();

beforeEach(() => {
  jest.resetAllMocks();
});

afterEach(() => {
  jest.restoreAllMocks();
});

describe("getUser", () => {
  it("rejects invalid id values", async () => {
    await expect(getUser(0)).rejects.toThrow("id must be a positive integer");
    await expect(getUser(-1)).rejects.toThrow("id must be a positive integer");
    await expect(getUser(1.2)).rejects.toThrow("id must be a positive integer");
  });

  it("returns row from database when present", async () => {
    jest.mocked(pool.query).mockResolvedValueOnce({ rows: [{ id: 7, name: "Ada", email: "ada@example.com" }] } as any);
    const result = await getUser(7);
    expect(result).toEqual({ id: 7, name: "Ada", email: "ada@example.com" });
    expect(pool.query).toHaveBeenCalledWith("SELECT id, name, email FROM users WHERE id = $1", [7]);
    expect(axios.get).not.toHaveBeenCalled();
  });

  it("falls back to profile api when database row is missing", async () => {
    jest.mocked(pool.query).mockResolvedValueOnce({ rows: [] } as any);
    jest.mocked(axios.get).mockResolvedValueOnce({ data: { id: 8, name: "Grace", email: "grace@example.com" } } as any);
    const result = await getUser(8);
    expect(result).toEqual({ id: 8, name: "Grace", email: "grace@example.com" });
    expect(pool.query).toHaveBeenCalledWith("SELECT id, name, email FROM users WHERE id = $1", [8]);
    expect(axios.get).toHaveBeenCalledWith("https://api.example.com/users/8");
  });
});

describe("importUser", () => {
  it("imports api user into database and lowercases email", async () => {
    jest.mocked(axios.get).mockResolvedValueOnce({ data: { id: 9, name: "Lin", email: "LIN@EXAMPLE.COM" } } as any);
    jest.mocked(pool.query).mockResolvedValueOnce({ rows: [] } as any);
    const result = await importUser(9);
    expect(result).toBe(true);
    expect(axios.get).toHaveBeenCalledWith("https://api.example.com/users/9");
    expect(pool.query).toHaveBeenCalledWith("INSERT INTO users (id, name, email) VALUES ($1, $2, $3)", [9, "Lin", "lin@example.com"]);
  });

  it("returns false when api responds with 404 axios error", async () => {
    const error = { response: { status: 404 } } as any;
    jest.mocked(axios.isAxiosError).mockReturnValue(true);
    jest.mocked(axios.get).mockRejectedValueOnce(error);
    const result = await importUser(10);
    expect(result).toBe(false);
    expect(pool.query).not.toHaveBeenCalled();
  });

  it("rethrows non-404 errors", async () => {
    const error = new Error("boom");
    jest.mocked(axios.isAxiosError).mockReturnValue(false);
    jest.mocked(axios.get).mockRejectedValueOnce(error);
    await expect(importUser(11)).rejects.toThrow("boom");
    expect(pool.query).not.toHaveBeenCalled();
  });
});

describe("countUsersByDomain", () => {
  it("counts users using lowercased domain", async () => {
    jest.mocked(pool.query).mockResolvedValueOnce({ rows: [{ count: "3" }] } as any);
    const result = await countUsersByDomain("Example.COM");
    expect(result).toBe(3);
    expect(pool.query).toHaveBeenCalledWith("SELECT COUNT(*) AS count FROM users WHERE email LIKE $1", ["%@example.com"]);
  });

  it("supports empty domain string", async () => {
    jest.mocked(pool.query).mockResolvedValueOnce({ rows: [{ count: "0" }] } as any);
    const result = await countUsersByDomain("");
    expect(result).toBe(0);
    expect(pool.query).toHaveBeenCalledWith("SELECT COUNT(*) AS count FROM users WHERE email LIKE $1", ["%@"]);
  });

  it("parses numeric string count from query result", async () => {
    jest.mocked(pool.query).mockResolvedValueOnce({ rows: [{ count: "12" }] } as any);
    const result = await countUsersByDomain("test.org");
    expect(result).toBe(12);
    expect(pool.query).toHaveBeenCalledTimes(1);
  });
});
